import os
import datetime
import six
import re
from lxml import etree
from ute_tshark.base import BaseTshark
from ute_tshark.exception import CapturingPacketsError, MessageNotFound, FieldOptionNullError
from ute_tshark.builder import CapturingCmdBuilder, ReadingCmdBuilder
from itertools import islice


class SavingPackets(BaseTshark):
    """ Class handles packets saving on virtual machine.

    :note: SSH protocol was used as a communication protocol.
    """
    def __init__(self, ssh_client, tshark_dir, interface, log_dir, pcap_name=None, snaplen=65555, pcap_size=None, preferences=None):
        """
        :param ssh_client:              SSHLibrary instance with established connection.
        :param string tshark_dir:       Path to dictionary where tshark is located.
        :param string interface:        Local or remote virtual machine interface which is used to packects capture.
        :param string log_dir:          Directory name where pcap file is stored.
        :param string pcap_name:        File name where packets are stored.
        :param integer snaplen:         Amount of data for each frame that is captured.
        :param string preferences:      Preference settings to be overridden.
        """
        super(SavingPackets, self).__init__(ssh_client, tshark_dir, interface, log_dir, snaplen, preferences)
        self._log_path = self._make_pcap_file_name(pcap_name)
        self._max_pcap_size = pcap_size
        self._org_log_dir = self._log_dir
        self._org_log_path = self._log_path

    @property
    def pcap_path(self):
        """Return path to pcap log file.

        :return:            Pcap log file path.
        :rtype:             string
        """
        return self._log_path

    def start_logging(self, capture_filter, log_dir=None, pcap_name=None):
        """Start capturing and savings traffic.

        :param string capture_filter:   Capture filter definition   (tshark -f equivalent).
        :param string log_dir:          Directory name where pcap file is stored.
        :param string pcap_name:        File name where packets are stored.

        """
        if log_dir or pcap_name:
            self._change_log_location_and_setup_log_dir(log_dir, pcap_name)
        cmd = self._build_start_logging_command(capture_filter)
        self.start_process(cmd)

    def stop_logging(self):
        """Stop capturing and saving traffic.

        """
        self._revert_to_setup_log_location()
        self.stop_process()

    def read_pcap(self, packet_filter='', output_type='text', pcap_file=None, decode_as=None, fields=None):
        """Read logs from pcap file and return as string.

        :param string packet_filter:        Expected packets content         (equivalent -R in tshark).
        :param string output_type:          Output form e.g pdml/text/       (equivalent -T in tshark).
        :param string pcap_file:            Pcap file to be read
        :param list fields:                 Field options to be read         (equivalent -e in tshark).

        :return:                            Packets matched with packet filter rules (text/xml) and/or the fields specified.
        :rtype:                             string

        :note: output_type will be automatically set as "fields" if fields parameter value is set.
        """
        pcap_to_read = pcap_file if pcap_file else self._log_path
        output_type = 'fields' if fields else output_type
        cmd = self._build_read_pcap_command(packet_filter, output_type, pcap_to_read, decode_as, fields)
        return self._execute(cmd)

    def download_pcap(self, destination):
        """Copy pcap file from the remote host to the specified destination path in the local machine.

        :param string destination:          Destination file path.

        :return:                            Source and destination path.
        :rtype:                             tuple
        """
        return self._get_file(src=self._log_path, dst=destination)

    def capture_packets_for_given_seconds(self, seconds, capture_filter='', log_dir=None, pcap_name=None):
        """Start capturing and savings traffic and wait until command execution finish.

        :param string seconds:          Time duration for packet capture (tshark -a duration:<seconds> equivalent).
        :param string capture_filter:   Capture filter definition   (tshark -f equivalent).
        :param string log_dir:          Directory name where pcap file is stored.
        :param string pcap_name:        File name where packets are stored.

        """
        if log_dir or pcap_name:
            self._change_log_location_and_setup_log_dir(log_dir, pcap_name)
        cmd = self._build_start_logging_command(capture_filter, seconds)
        self.start_process(cmd, int(seconds)-1)
        while self._process_is_not_stopped(100):
            pass
        self.pid = None
        self._revert_to_setup_log_location()

    def capture_given_packet_count_and_wait(self, packets, timeout=30, capture_filter='', log_dir=None, pcap_name=None):
        """Start capturing packets and wait until given packets are captured.

        :param string packets:          Number of packets to capture (tshark -c equivalent).
        :param string timeout:          Time duration for packet capture (tshark -a duration:<seconds> equivalent).
        :param string capture_filter:   Capture filter definition   (tshark -f equivalent).
        :param string log_dir:          Directory name where pcap file is stored.
        :param string pcap_name:        File name where packets are stored.

        """
        if log_dir or pcap_name:
            self._change_log_location_and_setup_log_dir(log_dir, pcap_name)
        cmd = self._build_start_logging_command(capture_filter, timeout, packets)
        self.start_process(cmd, 0)
        while self._process_is_not_stopped(100):
            pass
        packet_count = self._execute("{}/tshark -r {} | grep -c ^".format(self._tshark_dir, self._log_path))
        if int(packet_count) < int(packets):
            raise CapturingPacketsError("Unable to capture {} packets in {} seconds. "
                                        "Only able to capture {} packets.".format(packets, timeout, packet_count))
        self.pid = None
        self._revert_to_setup_log_location()

    def lookup_message_flow(self, messages, pcap_file_path=None):
        """Search for messages in pcap file read in pdml format. Returns true if order and duplication is correct.

        :param list messages:                messages that will be checked.
        :param string pcap_file_path:        Pcap file path where messages will be searched.

        :return boolean:                True if messages are found in order and correct frequency else False.

        """
        # Header in XML file has UTF8 encoding. It is assumed as is, and encoded in Python with default (UTF8)
        pdml_string = self.read_pcap(output_type='pdml', pcap_file=pcap_file_path).encode('utf-8')
        msg_frame_num = self._construct_messages_with_frame_numbers_dict(messages, pdml_string)
        return (self._is_count_correct_for_message_list(messages, msg_frame_num) and self._is_message_order_correct(messages, msg_frame_num))

    def lookup_messages_in_fields(self, message, fields, packet_filter='', pcap_file=None):
        """ Look up certain messages in the given field columns

        :param string messages:              messages that will be looked for.
        :param list fields:                  list of field options
        :param string packet_filter:         Deep packet filter definition.
        :param string pcap_file:             Pcap file path where messages will be searched.

        :return:                     Packets matched with packet filter rules and the look up message
        :rtype:                      string

        """
        if '' in fields or fields == []:
            raise FieldOptionNullError("Field option is null or contains null value")
        pcap_file = pcap_file or self._log_path
        read_pcap_file = self.read_pcap(packet_filter=packet_filter, pcap_file=pcap_file, fields=fields)
        messages = re.findall(".*{}.*".format(message), read_pcap_file)
        if messages:
            return '\n'.join(messages).strip()
        else:
            raise MessageNotFound("Unable to find \"{}\" messages".format(message))

    def _construct_messages_with_frame_numbers_dict(self, messages, input_string):
        msg_frame_num = {}
        unique_messages = set(messages)
        for message in unique_messages:
            msg_frame_num[message] = self._get_frame_numbers_of_packets_with_msg(message, input_string)
        return msg_frame_num

    def _get_frame_numbers_of_packets_with_msg(self, message, pdml_string):
        xpaths = self._get_all_xpath_expr(message)
        pdml_root = etree.fromstring(pdml_string)
        frames_with_msg = []
        for packet in pdml_root.iterchildren("*"):
            if self._xpath_check_if_all_message_conditions_are_in_packet(xpaths, packet):
                frames_with_msg.append(self._get_frame_number(packet))
        return frames_with_msg

    def _xpath_check_if_all_message_conditions_are_in_packet(self, xpaths, packet):
        return eval(' and '.join(["packet.xpath('{}')".format(xpath) for xpath in xpaths]))

    def _get_frame_number(self, packet):
        return int(*packet.xpath('.//field[@name="frame.number"]/@show'))

    def _get_all_xpath_expr(self, msg):
        conditions = [condition.strip().strip('()') for condition in msg.split('&&')]
        xpaths = []
        for condition in conditions:
            name_value_pair = [i.strip() for i in condition.split('==')]
            if len(name_value_pair) == 2:
                xpaths.append('.//field[@name="{}"][@show="{}"]'.format(name_value_pair[0], self._convert_to_dec_if_hex(name_value_pair[1])))
            else:
                xpaths.append('.//field[@name="{}"]'.format(condition))
        return xpaths

    def _convert_to_dec_if_hex(self, value):
        try:
            return int(value, 0)
        except ValueError:
            return value

    def _is_message_order_correct(self, messages, msg_frame_num):
        message_list = six.moves.zip_longest(messages, islice(messages, 1, None))
        for msg, next_msg in message_list:
            if next_msg is None:
                break
            if msg != next_msg and msg_frame_num[msg][0] > msg_frame_num[next_msg][0]:
                return False
            else:
                del(msg_frame_num[msg][0])
        return True

    def _is_count_correct_for_message_list(self, messages, msg_frame_num):
        for message in msg_frame_num:
            if messages.count(message) != len(msg_frame_num[message]):
                return False
        return True

    def _build_start_logging_command(self, capture_filter, duration='', packets=''):
        return CapturingCmdBuilder(self._tshark_dir, self._interface, capture_filter,
                                   self._log_path, self._snaplen, self._max_pcap_size,
                                   self._display_filter, self._preferences, self._log_dir, duration, packets).build()

    def _build_read_pcap_command(self, packet_filter, output_type, pcap_file_path, decode_as, fields):
        return ReadingCmdBuilder(self._tshark_dir, packet_filter, pcap_file_path,
                                 output_type, self._display_filter, self._preferences, decode_as, fields).build()

    def _change_log_location_and_setup_log_dir(self, log_dir, pcap_name):
        if log_dir:
            self._log_dir = log_dir
            self._setup_log_dir(log_dir)
        self._log_path = self._make_pcap_file_name(pcap_name)

    def _make_pcap_file_name(self, log_name):
        if log_name is None:
            log_name = ''.join(["tshark_", datetime.datetime.now().strftime("%y-%m-%d_%H-%M-%S"), '.pcap'])
        return os.path.join(self._log_dir, log_name)

    def _revert_to_setup_log_location(self):
        self._log_dir = self._org_log_dir
        self._log_path = self._org_log_path
